"""Fehler der Bestandsverwaltung."""


class BestandsFehler(Exception):
    """Grundklasse aller Fehler der Bestandsverwaltung."""


class DoppelterEintrag(BestandsFehler):
    def __init__(self, art, schluessel):
        super().__init__(f"{art} {schluessel!r} gibt es schon")
        self.art, self.schluessel = art, schluessel


class UnbekannterEintrag(BestandsFehler):
    def __init__(self, art, schluessel):
        super().__init__(f"{art} {schluessel!r} gibt es nicht")
        self.art, self.schluessel = art, schluessel


class UngueltigerEintrag(BestandsFehler):
    def __init__(self, art, schluessel, grund):
        super().__init__(f"{art} {schluessel!r}: {grund}")
        self.art, self.schluessel, self.grund = art, schluessel, grund

