"""Bestandsverwaltung der Stadtbibliothek: Verzeichnisse für Leser, Medien, Ausleihen und
alles, was daran hängt, mit Suche, Prüfung und CSV-Austausch."""

import csv
from collections import Counter
from dataclasses import dataclass, replace

from bibliothek.fehler import DoppelterEintrag, UnbekannterEintrag, UngueltigerEintrag

MAX_TEXT = 200


@dataclass
class Leser:
    """Ein Eintrag der Art Leser; Schlüssel ist `ausweis`."""

    ausweis: str
    name: str = ""
    adresse: str = ""
    geburtsjahr: int = 0
    gesperrt: bool = False

    def als_zeile(self):
        """Leser als Zeile für den CSV-Export, Felder in fester Reihenfolge."""
        return [
            self.ausweis,
            str(self.name),
            str(self.adresse),
            str(self.geburtsjahr),
            str(self.gesperrt),
        ]

    @classmethod
    def aus_zeile(cls, zeile):
        """Leser aus einer CSV-Zeile; fehlende Spalten bekommen den Standardwert."""
        werte = list(zeile) + [""] * (5 - len(zeile))
        return cls(
            ausweis=werte[0],
            name=werte[1],
            adresse=werte[2],
            geburtsjahr=int(werte[3] or 0),
            gesperrt=werte[4] == "True",
        )


class LeserVerzeichnis:
    """Alle Einträge der Art Leser, nach `ausweis` geordnet, mit Suche und Export."""

    def __init__(self):
        self._eintraege = {}
        self._protokoll = []

    def __len__(self):
        return len(self._eintraege)

    def __contains__(self, ausweis):
        return ausweis in self._eintraege

    def __iter__(self):
        return iter(sorted(self._eintraege.values(), key=lambda e: e.ausweis))

    def anlegen(self, eintrag):
        """Legt einen neuen Eintrag an; ein vorhandener Schlüssel ist ein Fehler."""
        self.pruefen(eintrag)
        if eintrag.ausweis in self._eintraege:
            raise DoppelterEintrag("Leser", eintrag.ausweis)
        self._eintraege[eintrag.ausweis] = eintrag
        self._protokoll.append(("anlegen", eintrag.ausweis))
        return eintrag

    def holen(self, ausweis):
        """Eintrag zum Schlüssel; ein unbekannter Schlüssel ist ein Fehler."""
        try:
            return self._eintraege[ausweis]
        except KeyError:
            raise UnbekannterEintrag("Leser", ausweis) from None

    def entfernen(self, ausweis):
        """Entfernt den Eintrag und gibt ihn zurück."""
        eintrag = self.holen(ausweis)
        del self._eintraege[ausweis]
        self._protokoll.append(("entfernen", ausweis))
        return eintrag

    def aendern(self, ausweis, **felder):
        """Setzt einzelne Felder; unbekannte Feldnamen sind ein Fehler."""
        eintrag = self.holen(ausweis)
        erlaubt = {"name", "adresse", "geburtsjahr", "gesperrt"}
        fremd = sorted(set(felder) - erlaubt)
        if fremd:
            grund = "unbekannte Felder: " + ", ".join(fremd)
            raise UngueltigerEintrag("Leser", ausweis, grund)
        neu = replace(eintrag, **felder)
        self.pruefen(neu)
        self._eintraege[ausweis] = neu
        self._protokoll.append(("aendern", ausweis))
        return neu

    def pruefen(self, eintrag):
        """Prüft die Felder eines Eintrags vor dem Speichern."""
        if not eintrag.ausweis or not eintrag.ausweis.strip():
            raise UngueltigerEintrag("Leser", eintrag.ausweis, "Schlüssel fehlt")
        if len(eintrag.name) > MAX_TEXT:
            raise UngueltigerEintrag("Leser", eintrag.ausweis, "name ist zu lang")
        if len(eintrag.adresse) > MAX_TEXT:
            raise UngueltigerEintrag("Leser", eintrag.ausweis, "adresse ist zu lang")
        if eintrag.geburtsjahr < 0:
            raise UngueltigerEintrag("Leser", eintrag.ausweis, "geburtsjahr ist negativ")

    def sortiert(self, absteigend=False):
        """Einträge nach `name`, bei Gleichstand nach `ausweis`."""
        return sorted(self._eintraege.values(),
                      key=lambda e: (e.name, e.ausweis), reverse=absteigend)

    def mit_gesperrt(self, wert):
        """Einträge, deren `gesperrt` gleich `wert` ist (bool)."""
        return [e for e in self if e.gesperrt == wert]

    def gruppiert(self):
        """Einträge je Wert von `gesperrt`, Gruppen sortiert."""
        gruppen = {}
        for eintrag in self:
            gruppen.setdefault(eintrag.gesperrt, []).append(eintrag)
        return dict(sorted(gruppen.items(), key=lambda kv: str(kv[0])))

    def suchen(self, text):
        """Einträge, in deren Textfeldern `text` vorkommt (ohne Groß/Klein)."""
        text = text.casefold()
        treffer = []
        for eintrag in self:
            felder = (eintrag.ausweis, eintrag.name, eintrag.adresse,)
            if any(text in feld.casefold() for feld in felder):
                treffer.append(eintrag)
        return treffer

    def exportieren(self, ziel):
        """Schreibt alle Einträge als CSV mit Kopfzeile nach `ziel` (Textdatei)."""
        schreiber = csv.writer(ziel, delimiter=";")
        schreiber.writerow(["ausweis", "name", "adresse", "geburtsjahr", "gesperrt"])
        for eintrag in self:
            schreiber.writerow(eintrag.als_zeile())
        return len(self)

    def importieren(self, quelle, ersetzen=False):
        """Liest Einträge aus einer CSV mit Kopfzeile; mit `ersetzen` gewinnt die Datei."""
        leser = csv.reader(quelle, delimiter=";")
        next(leser, None)
        gelesen = 0
        for zeile in leser:
            if not zeile:
                continue
            eintrag = Leser.aus_zeile(zeile)
            if eintrag.ausweis in self._eintraege and ersetzen:
                self.pruefen(eintrag)
                self._eintraege[eintrag.ausweis] = eintrag
            elif eintrag.ausweis not in self._eintraege:
                self.anlegen(eintrag)
            gelesen += 1
        return gelesen

    def statistik(self):
        """Anzahl je Wert von `gesperrt` und die Zahl der Änderungen."""
        zaehler = Counter(e.gesperrt for e in self)
        return {
            "anzahl": len(self),
            "je_gesperrt": dict(sorted(zaehler.items(), key=lambda kv: str(kv[0]))),
            "aenderungen": len(self._protokoll),
        }


