        """Setzt einzelne Felder; unbekannte Feldnamen sind ein Fehler."""
        eintrag = self.holen(signatur)
        erlaubt = {"gezaehlt", "erwartet", "zaehler", "datum"}
        fremd = sorted(set(felder) - erlaubt)
        if fremd:
            grund = "unbekannte Felder: " + ", ".join(fremd)
            raise UngueltigerEintrag("Inventurposten", signatur, grund)
        neu = replace(eintrag, **felder)
        self.pruefen(neu)
        self._eintraege[signatur] = neu
        self._protokoll.append(("aendern", signatur))
        return neu

    def pruefen(self, eintrag):
        """Prüft die Felder eines Eintrags vor dem Speichern."""
        if not eintrag.signatur or not eintrag.signatur.strip():
            raise UngueltigerEintrag("Inventurposten", eintrag.signatur, "Schlüssel fehlt")
        if eintrag.gezaehlt < 0:
            raise UngueltigerEintrag("Inventurposten", eintrag.signatur, "gezaehlt ist negativ")
        if eintrag.erwartet < 0:
            raise UngueltigerEintrag("Inventurposten", eintrag.signatur, "erwartet ist negativ")
        if len(eintrag.zaehler) > MAX_TEXT:
            raise UngueltigerEintrag("Inventurposten", eintrag.signatur, "zaehler ist zu lang")
        if eintrag.datum < 0:
            raise UngueltigerEintrag("Inventurposten", eintrag.signatur, "datum ist negativ")

    def sortiert(self, absteigend=False):
        """Einträge nach `datum`, bei Gleichstand nach `signatur`."""
        return sorted(self._eintraege.values(),
                      key=lambda e: (e.datum, e.signatur), reverse=absteigend)

    def mit_zaehler(self, wert):
        """Einträge, deren `zaehler` gleich `wert` ist (str)."""
        return [e for e in self if e.zaehler == wert]

    def gruppiert(self):
        """Einträge je Wert von `zaehler`, Gruppen sortiert."""
        gruppen = {}
        for eintrag in self:
            gruppen.setdefault(eintrag.zaehler, []).append(eintrag)
        return dict(sorted(gruppen.items(), key=lambda kv: str(kv[0])))

    def suchen(self, text):
        """Einträge, in deren Textfeldern `text` vorkommt (ohne Groß/Klein)."""
        text = text.casefold()
        treffer = []
        for eintrag in self:
            felder = (eintrag.signatur, eintrag.zaehler,)
            if any(text in feld.casefold() for feld in felder):
                treffer.append(eintrag)
        return treffer

    def exportieren(self, ziel):
        """Schreibt alle Einträge als CSV mit Kopfzeile nach `ziel` (Textdatei)."""
        schreiber = csv.writer(ziel, delimiter=";")
        schreiber.writerow(["signatur", "gezaehlt", "erwartet", "zaehler", "datum"])
        for eintrag in self:
            schreiber.writerow(eintrag.als_zeile())
        return len(self)

    def importieren(self, quelle, ersetzen=False):
        """Liest Einträge aus einer CSV mit Kopfzeile; mit `ersetzen` gewinnt die Datei."""
        leser = csv.reader(quelle, delimiter=";")
        next(leser, None)
        gelesen = 0
        for zeile in leser:
            if not zeile:
                continue
            eintrag = Inventurposten.aus_zeile(zeile)
            if eintrag.signatur in self._eintraege and ersetzen:
                self.pruefen(eintrag)
                self._eintraege[eintrag.signatur] = eintrag
            elif eintrag.signatur not in self._eintraege:
                self.anlegen(eintrag)
            gelesen += 1
        return gelesen

    def statistik(self):
        """Anzahl je Wert von `zaehler` und die Zahl der Änderungen."""
        zaehler = Counter(e.zaehler for e in self)
        return {
            "anzahl": len(self),
            "je_zaehler": dict(sorted(zaehler.items(), key=lambda kv: str(kv[0]))),
            "aenderungen": len(self._protokoll),
        }


class Bestand:
    """Alle Verzeichnisse der Bibliothek an einer Stelle."""

    def __init__(self):
        self.leser = LeserVerzeichnis()
        self.medium = MediumVerzeichnis()
        self.ausleihe = AusleiheVerzeichnis()
        self.vormerkung = VormerkungVerzeichnis()
        self.mahnung = MahnungVerzeichnis()
        self.gebuehr = GebuehrVerzeichnis()
        self.standort = StandortVerzeichnis()
        self.inventurposten = InventurpostenVerzeichnis()

    def verzeichnisse(self):
        """Name und Verzeichnis, in fester Reihenfolge."""
        return [
            ("leser", self.leser),
            ("medium", self.medium),
            ("ausleihe", self.ausleihe),
            ("vormerkung", self.vormerkung),
            ("mahnung", self.mahnung),
            ("gebuehr", self.gebuehr),
            ("standort", self.standort),
            ("inventurposten", self.inventurposten),
        ]

    def uebersicht(self):
        """Anzahl der Einträge je Verzeichnis."""
        return {name: len(verzeichnis) for name, verzeichnis in self.verzeichnisse()}
